'use client'
/** Tabs: the MATRIX card `ui-tabs` (interactive: pointer and keyboard edit its data). Generated by scripts/registry/generate.ts. */
import { MatrixDotCard, type MatrixDotCardProps } from '@/components/matrix/dot-card'
import { componentsBoard } from '@/lib/matrix/widgets/boards/components'

const preset = componentsBoard.find(p => p.id === 'ui-tabs')!

export type MatrixTabsProps = Omit<MatrixDotCardProps, 'preset'>

export function MatrixTabs(props: MatrixTabsProps) {
  return <MatrixDotCard preset={preset} {...props} />
}
